"""tabula.engine -- the table model, the transforms, the output formats and the command line.

This is the one module every command lives in. A command is a function `cmd_NAME(args, opts)` that gets the
positional arguments (a list of strings) and the options (a dict) and returns a Table, which `main` then prints in the
format asked for (`--format text|csv|json`, text by default). A mistake in a file or in a request raises TabulaError
(exit status 1); a command line that is not shaped right raises UsageError (exit status 2).
"""
import csv
import io
import json
import os
import re
import sys
import unicodedata
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, ROUND_FLOOR, ROUND_CEILING, ROUND_DOWN, getcontext

from .errors import TabulaError, UsageError

PROG = "tabula"
FORMATS = ("text", "csv", "json")
# The choice options every command line accepts: name -> allowed values; the first-listed default is in DEFAULTS.
CHOICES = {"format": FORMATS, "kind": ("inner", "left"), "keep": ("first", "last")}
DEFAULTS = {"format": "text", "kind": "inner", "keep": "first"}
getcontext().prec = 60

NUMBER = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)")


# --- numbers -------------------------------------------------------------------------------------------------

def to_decimal(text):
    """The Decimal a cell holds, or None when it is not a plain decimal number (no exponent, no thousands marks)."""
    text = text.strip()
    if not NUMBER.fullmatch(text):
        return None
    try:
        return Decimal(text)
    except InvalidOperation:
        return None


def fmt_decimal(number):
    """A Decimal as plain text: no exponent, no negative zero."""
    text = format(number, "f")
    if text.startswith("-") and not text.strip("-0."):
        text = text[1:]
    return text


def _need_number(value):
    number = to_decimal(value)
    if number is None:
        raise TabulaError("%r is not a number" % value)
    return number


def _need_cell_number(table, row_number, column, value):
    """The Decimal in a cell that must be a number; the mistake names the file, the data row (from 1) and the column."""
    try:
        return _need_number(value)
    except TabulaError as exc:
        raise TabulaError("%s: row %d: column %r: %s" % (table.source, row_number, column, exc))


def _need_count(arg, name):
    if arg is None or not arg.isdigit():
        raise TabulaError("%s needs a whole number argument, got %r" % (name, arg))
    return int(arg)


def _need_decimal_arg(arg, name):
    number = None if arg is None else to_decimal(arg)
    if number is None:
        raise TabulaError("%s needs a number argument, got %r" % (name, arg))
    return number


def _no_arg(name, arg):
    if arg is not None:
        raise TabulaError("%s takes no argument, got %r" % (name, arg))


def _need_text(arg, name):
    if arg is None:
        raise TabulaError("%s needs an argument" % name)
    return arg


# --- the table -----------------------------------------------------------------------------------------------

class Table:
    """Column names and rows of strings. `source` names where it came from, for messages."""

    def __init__(self, columns, rows, source="<table>"):
        self.columns = list(columns)
        self.rows = [list(r) for r in rows]
        self.source = source

    def __len__(self):
        return len(self.rows)

    def index(self, name):
        """Position of a column; TabulaError when there is none."""
        try:
            return self.columns.index(name)
        except ValueError:
            raise TabulaError("%s: no column %r (columns: %s)" % (self.source, name, ", ".join(self.columns)))

    def column(self, name):
        at = self.index(name)
        return [row[at] for row in self.rows]

    def dicts(self):
        return [dict(zip(self.columns, row)) for row in self.rows]

    def with_rows(self, rows, columns=None):
        return Table(self.columns if columns is None else columns, rows, self.source)


def parse_text(text, source):
    for fn, arg in specs:
        value = fn(value, arg)
    return value


# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage):
    if len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _need_min_args(args, count, usage):
    if len(args) < count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    _need_min_args(args, 3, "apply FILE COLUMN TRANSFORM...")
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise TabulaError("%s: row %d: %s" % (table.source, number, exc))
        rows.append(row)
    return table.with_rows(rows)


def _parse_sort_key(spec):
    """`COLUMN[:num][:desc]` (modifiers in either order) into (column, numeric, descending)."""
    column, *modifiers = spec.split(":")
    if not column:
        raise UsageError("sort: empty column name in key %r" % spec)
    for modifier in modifiers:
        if modifier not in ("num", "desc"):
            raise UsageError("sort: unknown modifier %r in key %r" % (modifier, spec))
    if len(set(modifiers)) != len(modifiers):
        raise UsageError("sort: modifier given twice in key %r" % spec)
    return column, "num" in modifiers, "desc" in modifiers


def cmd_sort(args, opts):
    _need_min_args(args, 2, "sort FILE KEY...")
    keys = [_parse_sort_key(spec) for spec in args[1:]]
    table = load(args[0])
    positions = [table.index(column) for column, _, _ in keys]
    values = []
    for number, row in enumerate(table.rows, 1):
        values.append([_need_cell_number(table, number, column, row[at]) if numeric else row[at]
                       for (column, numeric, _), at in zip(keys, positions)])
    order = list(range(len(table.rows)))
    for k in range(len(keys) - 1, -1, -1):
        order.sort(key=lambda i: values[i][k], reverse=keys[k][2])
    return table.with_rows([table.rows[i] for i in order])


FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")


def _parse_condition(spec):
    """`COLUMN OP VALUE` into (column, operator, value): the leftmost operator wins, the longer one at the same spot."""
    best = None
    for op in FILTER_OPERATORS:
        at = spec.find(op)
        if at >= 0 and (best is None or at < best[0] or (at == best[0] and len(op) > len(best[1]))):
            best = (at, op)
    if best is None:
        raise UsageError("filter: no operator in condition %r" % spec)
    at, op = best
    if at == 0:
        raise UsageError("filter: no column name in condition %r" % spec)
    return spec[:at], op, spec[at + len(op):]


def _condition_holds(cell, op, value):
    if op == "~":
        return value.lower() in cell.lower()
    left, right = to_decimal(cell), to_decimal(value)
    if left is None or right is None:
        left, right = cell, value
    return {"==": left == right, "!=": left != right, ">=": left >= right,
            "<=": left <= right, ">": left > right, "<": left < right}[op]


def cmd_filter(args, opts):
    _need_min_args(args, 2, "filter FILE CONDITION...")
    conditions = [_parse_condition(spec) for spec in args[1:]]
    table = load(args[0])
    positions = [table.index(column) for column, _, _ in conditions]
    return table.with_rows([row for row in table.rows
                            if all(_condition_holds(row[at], op, value)
                                   for at, (_, op, value) in zip(positions, conditions))])


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "the rows ordered by one or more keys"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "the rows where every condition holds"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS..." % PROG, "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = dict(DEFAULTS), [], 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            rest.extend(argv[i + 1:])
            break
        name = arg[2:].split("=", 1)[0] if arg.startswith("--") else None
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in CHOICES:
            if "=" in arg:
                value = arg.split("=", 1)[1]
            else:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            if value not in CHOICES[name]:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(CHOICES[name]), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 0
    except OSError as exc:
        # a full disk or a dead descriptor: say so once, and keep the exit flush from failing again
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except (OSError, ValueError):
            pass
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1
# Commands

`tabula [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS...` reads CSV files (UTF-8, an optional byte order mark, LF or CRLF) and prints
a table. Every command returns a `Table`; `--format` says how it is printed (text by default). A mistake in a file or in a
request exits 1 with `tabula: <message>` on standard error; a command line that is not shaped right exits 2. Options may stand
before or after the command, as `--opt VALUE` or `--opt=VALUE`; `--` ends them, so an argument that starts with a dash can
follow it. Output that cannot be written (a full disk, say) exits 1.

## show

`tabula show FILE` prints the whole table. Blank lines in the file are ignored. A row with more or fewer fields than the
header is a mistake that names the file and the line (`t.csv: line 3: expected 2 fields, found 1`).

## head

`tabula head FILE N` prints the header and the first N rows. N is a whole number (zero is fine); anything else is a usage
error.

## cols

`tabula cols FILE` prints one row per column with two columns, `position` (from 1) and `column`.

## apply

`tabula apply FILE COLUMN TRANSFORM...` runs each TRANSFORM, left to right, over every value of one column and prints the
whole table. A transform is `name` or `name:ARG`; the list is in `docs/transforms.md`. A value a transform cannot take is
a mistake that names the file and the row (`t.csv: row 2: 'abc' is not a number`). Rows count from 1, the header not
counted.

## sort

`tabula sort FILE KEY...` prints the whole table with its rows ordered by the keys. The first key decides; each later key
only orders rows the keys before it leave tied. A KEY is `COLUMN`, `COLUMN:num`, `COLUMN:desc` or `COLUMN:num:desc`; the
two modifiers may come in either order. Without `:num` values compare as text, by code point, so `B` comes before `a`.
With `:num` they compare as numbers. `:desc` puts the largest first. Rows that tie on every key keep their file order,
also with `:desc`.

A value that is not a number under `:num`, an empty cell included, is a mistake that names the file, the row and the
column (`t.csv: row 3: column 'price': 'abc' is not a number`). Rows count from 1 in file order, the header not counted.
A column that does not exist is a mistake that names it. No KEY, an unknown modifier, a modifier given twice, or an empty
column name is a usage error, reported before the file is read.

## filter

`tabula filter FILE CONDITION...` prints the header and the rows for which every CONDITION holds, in file order. A
CONDITION is `COLUMN`, an operator and a `VALUE`, written as one argument: `price>=10`, `city==Oslo`, `name~ann`. The
operators are `==`, `!=`, `>=`, `<=`, `>`, `<` and `~`. The operator is the leftmost one in the argument; where two start at
the same place the longer wins, so `price>=10` reads as `>=` and not `>`. The VALUE is the rest of the argument and may be
empty (`note==` keeps the rows whose `note` is empty).

For every operator except `~`, a cell and a VALUE that are both numbers compare as numbers (`10>9` holds, `1.0==1` holds);
otherwise they compare as text, by code point. `~` holds when the cell contains the VALUE, case aside. When no row is left
the header is still printed (`[]` for `--format json`).

A COLUMN the file does not have is a mistake that names it (exit 1). No CONDITION, a condition with no operator, or
nothing before the operator is a usage error (exit 2), reported before the file is read.
